testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { problemasDaSenha, mascararSegredo } from './solution.mjs';

test('senha forte não tem nenhum problema', () => {
  assert.deepEqual(problemasDaSenha('Abcdef1!'), []);
});

test('senha fraca lista todos os problemas que faltam', () => {
  assert.deepEqual(problemasDaSenha('abc'), [
    'pouco_comprida',
    'sem_maiuscula',
    'sem_numero',
    'sem_caractere_especial'
  ]);
  assert.deepEqual(problemasDaSenha(42), ['invalida']);
});

test('mascararSegredo esconde o meio e preserva as pontas', () => {
  assert.equal(mascararSegredo('segredo123'), 'se******23');
  assert.equal(mascararSegredo('abcdefgh'), 'ab****gh');
});

test('mascararSegredo lança com segredo curto ou não-string', () => {
  assert.throws(() => mascararSegredo('abc'), /curto/);
  assert.throws(() => mascararSegredo(42), /curto/);
});

solutionCode:
export function problemasDaSenha(senha) {
  if (typeof senha !== 'string') return ['invalida'];
  const problemas = [];
  if (senha.length < 8) problemas.push('pouco_comprida');
  if (!/[A-Z]/.test(senha)) problemas.push('sem_maiuscula');
  if (!/[a-z]/.test(senha)) problemas.push('sem_minuscula');
  if (!/[0-9]/.test(senha)) problemas.push('sem_numero');
  if (!/[^a-zA-Z0-9]/.test(senha)) problemas.push('sem_caractere_especial');
  return problemas;
}

export function mascararSegredo(segredo) {
  if (typeof segredo !== 'string' || segredo.length < 5) {
    throw new Error('segredo curto demais');
  }
  return segredo.slice(0, 2) + '*'.repeat(segredo.length - 4) + segredo.slice(-2);
}
